try{$ds->regroup($ids,false,(int)$actor->ID);$merged=$db->get_col("SELECT topic_id FROM {$s->prefix}discovery WHERE item_id IN (5559,5600) ORDER BY item_id");cdra_need(count($merged)===2&&$merged[0]===$merged[1],'real_merge_failed');$ds->regroup([5600],true,(int)$actor->ID);$split=$db->get_col("SELECT topic_id FROM {$s->prefix}discovery WHERE item_id IN (5559,5600) ORDER BY item_id");cdra_need($split[0]!==$split[1],'real_split_failed');$ds->regroup($ids,false,(int)$actor->ID);$s->put('stabilization_sap_event',['record_ids'=>$ids,'reason'=>'Two independent reports of SAP November 2026 ICM2SHELL/PROXYGATE security updates, same publication day; not CVE-only matching','actor'=>(int)$actor->ID,'at'=>time()]);echo wp_json_encode(['status'=>'PASS','record_ids'=>$ids,'merge_split_merge'=>true,'publications_preserved'=>true,'reason'=>'Same vendor, unique named vulnerabilities and same update event/date; source publications kept separately']);}finally{$db->get_var($db->prepare('SELECT RELEASE_LOCK(%s)',$lock));}
